 IEnumerator Guard(IEnumerator task){var stack=new Stack<IEnumerator>();stack.Push(task);while(stack.Count>0){var a=stack.Peek();bool more=false;object v=null;try{more=a.MoveNext();if(more)v=a.Current;}catch(Exception e){Check(false,"EXCEPTION "+e);break;}if(!more){stack.Pop();continue;}if(v is IEnumerator nested)stack.Push(nested);else yield return v;}P07EvidenceRecorder.Stop();Label("DONE checks="+checks.Count+" failures="+checks.Count(x=>x.StartsWith("FAIL")));Cleanup();}
